for reminder in reminders:
    task = reminder.task

    if reminder.kind == FamilyTaskReminder.Kind.EVENT_REMINDER:
        # The event link was removed (e.g. the event was deleted, which
        # nulls linked_event via SET_NULL). Drop the orphaned reminder so
        # it never fires with stale copy.
        if task.linked_event_id is None:
            reminder.delete()
            continue
        event_title = str(task.linked_event.title or "the event").strip()
        title = f"Reminder: {task.title}"
        if task.linked_event_anchor == FamilyTask.EventAnchor.START:
            message = f"Before {event_title} — don't forget: {task.title}."
