def validate(self, attrs: Any) -> Any:
    start = attrs.get("due_window_start_at")
    end = attrs.get("due_window_end_at")
    if start is not None and end is not None and end < start:
        raise serializers.ValidationError(
            {"due_window_end_at": "Due window end must be on or after the start."}
        )
    return attrs

